const html = $input.first().json.html;
if (typeof html !== 'string') throw new Error('Falta la ficha de Sercotec');
const band = html.replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').match(/ventas netas demostrables anuales mayores o iguales a ([\d.]+) UF e inferiores o iguales a ([\d.]+) UF/i);
const links = [...new Set([...html.matchAll(/href="(https:\/\/www\.sercotec\.cl\/[^"]*Bases-de-Convocatoria_Crece-Multisectorial[^"]*\.pdf)"/gi)].map(match => match[1]))];
if (!band || links.length !== 1) throw new Error('Revisar ficha oficial: rango o bases no reconocidos');
const source = 'https://www.sercotec.cl/convocatoria/crece-multisectorial-provincia-de-iquique-region-de-tarapaca-2026/';
const previous = [200,25000];
const current = band.slice(1).map(n => Number(n.replaceAll('.','')));
const file = 'https://www.sercotec.cl/wp-content/uploads/2026/06/Bases-de-Convocatoria_Crece-Multisectorial-2026_Provincia-de-Iquique_Region-de-Tarapaca.pdf';
const pendientes = [];
if (String(previous)!==String(current)) pendientes.push({expediente:'H&S',fuente:source,requisito:'ventas_uf',documento:'Carpeta tributaria',anterior:previous,actual:current});
if (links[0]!==file) pendientes.push({expediente:'H&S',fuente:source,requisito:'bases',documento:'Bases y checklist',anterior:file,actual:links[0]});
return [{json:{pendientes}}];

const rows = $input.first().json.pendientes;
if (!Array.isArray(rows)) throw new Error('Se requiere el arreglo pendientes del radar');
const source = 'https://www.sercotec.cl/convocatoria/crece-multisectorial-provincia-de-iquique-region-de-tarapaca-2026/';
for (const row of rows) {
  if (row.expediente !== 'H&S' || row.fuente !== source ||
      !['ventas_uf', 'bases'].includes(row.requisito) ||
      typeof row.documento !== 'string') throw new Error('Pendiente inválido');
}
if (!rows.length) return [];
const body = rows.map(row => [
  '### ' + row.requisito,
  'Anterior: ' + JSON.stringify(row.anterior),
  'Actual: ' + JSON.stringify(row.actual),
  'Respaldo por revisar: ' + row.documento,
  'Fuente: ' + row.fuente
].join('\n')).join('\n\n');
return [{json:{title:'[Radar H&S] Crece Iquique · revisión de cambios',body}}];
